//! `sermofur_core::sources` against the tables that the .NET code produced
//! (`rust/tests/golden/sources.json` on Windows, `sources-unix.json` on Linux; on macOS only the
//! tables that do not depend on the system), regenerated by `rust/tools/source-oracle`.
//!
//! Ports of `SourceTests`: `ReaderAcceptsABomAndHashesExactlyTheBytesRead` (snapshot
//! `bom_text`), `PassagesAreBoundedAndKeepEveryCharacter` (split case with `mot 😀 ` and the
//! properties below), the reader part of `UnindexableFilesAreRefusedWithAStableCode` (reads
//! `blank`, `nul`, `latin1`, `bound_plus_one`, `missing`, `directory`) and of
//! `FileReachedThroughALinkIsRefused` (reads `dir_link`, `junction`); of `HardeningTests`,
//! `SpecialFileIsNotReadAsASource` (read `fifo`, Linux).

use std::fs;
use std::path::{MAIN_SEPARATOR_STR, PathBuf};

use proptest::prelude::*;
use serde_json::Value;
use sermofur_core::error::SermofurError;
use sermofur_core::ownership::SystemOwnership;
use sermofur_core::search::SearchDocument;
use sermofur_core::sources::{
    MAX_PASSAGE_LENGTH, SourceSnapshot, read, refuse_unindexable, snapshot, split,
};
use sermofur_core::store::sha256_upper;
use uuid::Uuid;

fn golden() -> Value {
    let file = if cfg!(windows) {
        "sources.json"
    } else {
        "sources-unix.json"
    };
    let path = format!("{}/../../tests/golden/{file}", env!("CARGO_MANIFEST_DIR"));
    serde_json::from_str(&fs::read_to_string(path).expect("golden file")).expect("JSON")
}

fn rows<'a>(golden: &'a Value, table: &str) -> &'a Vec<Value> {
    golden[table].as_array().expect("table")
}

fn hex(text: &str) -> Vec<u8> {
    (0..text.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&text[i..i + 2], 16).expect("hex"))
        .collect()
}

/// Segments `[piece, count]`, each piece repeated then joined.
fn segments(value: &Value) -> Vec<(&str, usize)> {
    value
        .as_array()
        .expect("segments")
        .iter()
        .map(|s| {
            let count = usize::try_from(s[1].as_u64().expect("count")).expect("count");
            (s[0].as_str().expect("piece"), count)
        })
        .collect()
}

fn bytes_of(value: &Value) -> Vec<u8> {
    segments(value)
        .into_iter()
        .flat_map(|(piece, count)| hex(piece).repeat(count))
        .collect()
}

fn text_of(value: &Value) -> String {
    segments(value)
        .into_iter()
        .map(|(piece, count)| piece.repeat(count))
        .collect()
}

fn sha256(bytes: &[u8]) -> String {
    sha256_upper(bytes).to_ascii_lowercase()
}

fn check_passages(context: &str, expected: &Value, actual: &[SearchDocument]) {
    let expected = expected.as_array().expect("passages");
    assert_eq!(expected.len(), actual.len(), "{context}: passage count");
    for (want, (number, text)) in expected.iter().zip(actual) {
        assert_eq!(
            want["passage"].as_i64(),
            Some(i64::from(*number)),
            "{context}"
        );
        assert_eq!(
            want["units"].as_u64(),
            Some(text.encode_utf16().count() as u64),
            "{context}: passage {number} length"
        );
        assert_eq!(
            want["sha256"].as_str(),
            Some(sha256(text.as_bytes()).as_str()),
            "{context}: passage {number}"
        );
        if let Some(want) = want.get("text") {
            assert_eq!(want.as_str(), Some(text.as_str()), "{context}");
        }
    }
}

fn check_refusal(context: &str, expected: &Value, actual: Result<(), SermofurError>) {
    match actual {
        Ok(()) => assert!(expected.is_null(), "{context}: refusal {expected} expected"),
        Err(error) => {
            assert_eq!(
                expected["code"].as_str(),
                Some(error.code.as_str()),
                "{context}"
            );
            assert_eq!(
                expected["message"].as_str(),
                Some(error.message.as_str()),
                "{context}"
            );
            assert_eq!(
                expected["exitCode"].as_i64(),
                Some(i64::from(error.exit_code)),
                "{context}"
            );
        }
    }
}

/// Status, hash, size, rejection, passages and refusal, the names of the .NET members being
/// those of the Rust variants.
fn check_snapshot(context: &str, expected: &Value, actual: &SourceSnapshot) {
    assert_eq!(
        expected["status"].as_str(),
        Some(format!("{:?}", actual.status).as_str()),
        "{context}: status"
    );
    assert_eq!(
        expected["hash"].as_str(),
        Some(actual.hash.as_str()),
        "{context}"
    );
    assert_eq!(
        expected["size"].as_i64(),
        Some(actual.size),
        "{context}: size"
    );
    assert_eq!(
        expected["rejection"].as_str().map(str::to_owned),
        actual.rejection.map(|r| format!("{r:?}")),
        "{context}: rejection"
    );
    check_passages(context, &expected["passages"], &actual.passages);
    check_refusal(context, &expected["refusal"], refuse_unindexable(actual));
}

#[test]
fn white_space_is_that_of_the_oracle() {
    let golden = golden();
    let expected: Vec<u32> = rows(&golden, "whitespace")
        .iter()
        .map(|u| u32::try_from(u.as_u64().expect("unit")).expect("unit"))
        .collect();
    let actual: Vec<u32> = (0..=0xFFFF)
        .filter(|u| char::from_u32(*u).is_some_and(char::is_whitespace))
        .collect();
    assert_eq!(expected, actual);
    // Through the reader: a text of white space only is empty, any other character is text.
    let blank: String = actual.iter().filter_map(|u| char::from_u32(*u)).collect();
    assert_eq!(
        snapshot(blank.as_bytes()).rejection,
        Some(sermofur_core::records::SourceRejection::Empty)
    );
    // U+FEFF alone is a BOM, removed before decoding.
    for c in (1..=0xFFFF)
        .filter_map(char::from_u32)
        .filter(|c| *c != '\u{feff}')
    {
        let indexed = snapshot(c.to_string().as_bytes()).passages.len() == 1;
        assert_eq!(indexed, !c.is_whitespace(), "U+{:04X}", u32::from(c));
    }
}

#[test]
fn strict_utf8_decodes_as_the_oracle() {
    let golden = golden();
    let probes = rows(&golden, "utf8");
    assert!(probes.len() > 5000);
    for probe in probes {
        let bytes = hex(probe["hex"].as_str().expect("hex"));
        let decoded = std::str::from_utf8(&bytes).ok();
        assert_eq!(probe["text"].as_str(), decoded, "{}", probe["hex"]);
    }
}

#[test]
fn snapshots_match_the_oracle() {
    let golden = golden();
    for row in rows(&golden, "snapshots") {
        let name = row["name"].as_str().expect("name");
        check_snapshot(name, row, &snapshot(&bytes_of(&row["bytes"])));
    }
}

#[test]
fn passages_match_the_oracle() {
    let golden = golden();
    let cases = rows(&golden, "splits");
    assert!(cases.len() > 250);
    for (index, case) in cases.iter().enumerate() {
        let text = text_of(&case["text"]);
        check_passages(&format!("split {index}"), &case["passages"], &split(&text));
    }
}

/// The folder of all read cases, removed on drop, even after a failed assertion.
struct Scratch(PathBuf);

impl Drop for Scratch {
    fn drop(&mut self) {
        let _ = fs::remove_dir_all(&self.0);
    }
}

/// A folder of a read case, removed on drop once its handles are closed and its rights back.
struct Case {
    folder: PathBuf,
    held: Vec<fs::File>,
    denied: Vec<PathBuf>,
}

impl Drop for Case {
    fn drop(&mut self) {
        self.held.clear();
        for path in &self.denied {
            #[cfg(windows)]
            {
                let user = std::env::var("USERNAME").unwrap_or_default();
                let _ = std::process::Command::new("icacls")
                    .arg(path)
                    .args(["/remove:d", &user])
                    .output();
            }
            #[cfg(unix)]
            {
                use std::os::unix::fs::PermissionsExt;
                let _ = fs::set_permissions(path, fs::Permissions::from_mode(0o700));
            }
        }
        let _ = fs::remove_dir_all(&self.folder);
    }
}

fn run(command: &mut std::process::Command) {
    let out = command.output().expect("runs");
    assert!(out.status.success(), "{command:?} failed: {out:?}");
}

/// Replays one setup step of the oracle; false when the machine refuses symbolic links.
fn apply(case: &mut Case, step: &Value) -> bool {
    let under = |relative: &str| case.folder.join(relative.replace('/', MAIN_SEPARATOR_STR));
    let path = under(step["path"].as_str().expect("path"));
    let target = || under(step["target"].as_str().expect("target"));
    match step["op"].as_str().expect("op") {
        "file" => fs::write(&path, bytes_of(&step["bytes"])).expect("file"),
        "dir" => fs::create_dir_all(&path).expect("dir"),
        "fileLink" | "dirLink" => {
            #[cfg(windows)]
            let made = if step["op"] == "fileLink" {
                std::os::windows::fs::symlink_file(target(), &path)
            } else {
                std::os::windows::fs::symlink_dir(target(), &path)
            };
            #[cfg(unix)]
            let made = std::os::unix::fs::symlink(target(), &path);
            if let Err(error) = made {
                eprintln!("symbolic link refused: {error}");
                return false;
            }
        }
        "junction" => {
            #[cfg(windows)]
            run(std::process::Command::new("cmd")
                .args(["/C", "mklink", "/J"])
                .arg(&path)
                .arg(target()));
            #[cfg(unix)]
            std::os::unix::fs::symlink(target(), &path).expect("symlink");
        }
        "readOnly" => {
            let mut permissions = fs::metadata(&path).expect("file").permissions();
            permissions.set_readonly(true);
            fs::set_permissions(&path, permissions).expect("read-only");
        }
        "denyRead" => {
            #[cfg(windows)]
            run(std::process::Command::new("icacls").arg(&path).args([
                "/deny",
                &format!("{}:(RD)", std::env::var("USERNAME").expect("USERNAME")),
            ]));
            #[cfg(unix)]
            {
                use std::os::unix::fs::PermissionsExt;
                fs::set_permissions(&path, fs::Permissions::from_mode(0o000)).expect("mode");
            }
            case.denied.push(path);
        }
        "lock" => {
            #[cfg(windows)]
            let file = {
                use std::os::windows::fs::OpenOptionsExt;
                fs::OpenOptions::new()
                    .read(true)
                    .share_mode(0)
                    .open(&path)
                    .expect("lock")
            };
            #[cfg(unix)]
            let file = {
                let file = fs::File::open(&path).expect("open");
                file.lock().expect("flock");
                file
            };
            case.held.push(file);
        }
        "fifo" => run(std::process::Command::new("mkfifo").arg(&path)),
        other => panic!("unknown step {other}"),
    }
    true
}

#[test]
fn reads_match_the_oracle() {
    if cfg!(target_os = "macos") {
        // No table recorded on macOS: the system tables are those of Windows and Linux.
        return;
    }
    let golden = golden();
    let allow_skip = std::env::var("SERMOFUR_ALLOW_SYMLINK_SKIP").is_ok_and(|v| v == "1");
    // The root as the oracle passes it, a full path: on Windows its 8.3 names expanded, as
    // `Path.GetFullPath(Path.GetTempPath())`.
    let scratch = Scratch(
        sermofur_core::discovery::expand_short_names(&std::env::temp_dir()).join(format!(
            "sermofur-source-golden-{}",
            Uuid::new_v4().simple()
        )),
    );
    let mut checked = 0;
    for (index, row) in rows(&golden, "reads").iter().enumerate() {
        let name = row["name"].as_str().expect("name");
        let mut case = Case {
            folder: scratch.0.join(format!("c{index}")),
            held: Vec::new(),
            denied: Vec::new(),
        };
        // Root reads past mode 000 (CAP_DAC_OVERRIDE): the oracle's denied reads only hold for
        // another user.
        #[cfg(any(target_os = "linux", target_os = "macos"))]
        if rustix::process::geteuid().is_root()
            && row["setup"]
                .as_array()
                .expect("setup")
                .iter()
                .any(|step| step["op"] == "denyRead")
        {
            eprintln!("{name}: skipped as root, mode 000 does not stop root");
            continue;
        }
        fs::create_dir_all(&case.folder).expect("folder");
        let mut ready = true;
        for step in row["setup"].as_array().expect("setup") {
            ready = ready && apply(&mut case, step);
        }
        if !ready {
            assert!(
                allow_skip,
                "{name}: symlink creation refused (SERMOFUR_ALLOW_SYMLINK_SKIP=1 allows it)"
            );
            continue;
        }
        let root = case.folder.join(row["root"].as_str().expect("root"));
        let result = read(&root, row["path"].as_str().expect("path"), &SystemOwnership);
        match (result, row.get("exception"), row.get("error")) {
            (Ok(actual), None, None) => check_snapshot(name, row, &actual),
            // `CommandRunner` maps an `ArgumentException` to `invalid_storage_or_path`.
            (Err(error), Some(exception), None) => {
                assert_eq!(exception, "System.ArgumentException", "{name}");
                assert_eq!(error.code, "invalid_storage_or_path", "{name}");
                assert_eq!(error.exit_code, 3, "{name}");
            }
            (Err(error), None, Some(expected)) => check_refusal(name, expected, Err(error)),
            (actual, _, _) => panic!("{name}: {actual:?}, expected {row}"),
        }
        checked += 1;
        drop(case);
    }
    assert!(checked >= 30 || allow_skip, "{checked} reads checked");
}

/// Well-formed UTF-8 after Unicode table 3-7, written apart from the standard library.
fn well_formed(bytes: &[u8]) -> bool {
    let mut i = 0;
    while i < bytes.len() {
        let b = bytes[i];
        let (length, second) = match b {
            0x00..=0x7F => (1, 0x80..=0xBF),
            0xC2..=0xDF => (2, 0x80..=0xBF),
            0xE0 => (3, 0xA0..=0xBF),
            0xE1..=0xEC | 0xEE..=0xEF => (3, 0x80..=0xBF),
            0xED => (3, 0x80..=0x9F),
            0xF0 => (4, 0x90..=0xBF),
            0xF1..=0xF3 => (4, 0x80..=0xBF),
            0xF4 => (4, 0x80..=0x8F),
            _ => return false,
        };
        if length > 1 {
            if i + length > bytes.len() || !second.contains(&bytes[i + 1]) {
                return false;
            }
            if !bytes[i + 2..i + length]
                .iter()
                .all(|c| (0x80..=0xBF).contains(c))
            {
                return false;
            }
        }
        i += length;
    }
    true
}

/// Texts made of runs of pieces around the bounds, as the oracle's pseudo-random cases.
fn texts() -> impl Strategy<Value = String> {
    let pieces = prop::sample::select(vec![
        "a", "mot ", " ", "\n", "\r\n", "\r", "😀", "é", "\t", "\u{2028}", "\u{a0}", "x\n\ny",
        "\n\n", "\0",
    ]);
    let counts = prop_oneof![1usize..8, 990usize..1010, 1990usize..2010, 3990usize..4010];
    prop::collection::vec((pieces, counts), 0..7).prop_map(|runs| {
        runs.into_iter()
            .map(|(piece, count)| piece.repeat(count.div_ceil(piece.chars().count())))
            .collect()
    })
}

fn non_white(text: &str) -> String {
    text.chars().filter(|c| !c.is_whitespace()).collect()
}

proptest! {
    #![proptest_config(ProptestConfig::with_cases(256))]

    /// Strict decoding refuses exactly what table 3-7 refuses; the hash and the size always
    /// describe the bytes read; nothing panics.
    #[test]
    fn decoding_is_strict(bytes in prop_oneof![
        prop::collection::vec(any::<u8>(), 0..40),
        // Valid text, with or without a BOM and a NUL, then at most one byte changed: most
        // inputs stay well formed and reach the BOM and NUL branches.
        (
            prop::collection::vec(any::<char>(), 0..20),
            any::<bool>(),
            any::<bool>(),
            prop::option::of((any::<prop::sample::Index>(), any::<u8>())),
        )
            .prop_map(|(chars, bom, nul, change)| {
                let mut bytes = if bom { b"\xEF\xBB\xBF".to_vec() } else { Vec::new() };
                bytes.extend(chars.iter().collect::<String>().bytes());
                if nul {
                    bytes.push(0);
                }
                if let Some((index, byte)) = change
                    && !bytes.is_empty()
                {
                    let at = index.index(bytes.len());
                    bytes[at] = byte;
                }
                bytes
            }),
    ]) {
        let shot = snapshot(&bytes);
        prop_assert_eq!(&shot.hash, &sha256(&bytes));
        prop_assert_eq!(shot.size, bytes.len() as i64);
        let content = bytes.strip_prefix(b"\xEF\xBB\xBF").unwrap_or(&bytes);
        let binary = !well_formed(content) || content.contains(&0);
        prop_assert_eq!(
            shot.rejection == Some(sermofur_core::records::SourceRejection::Binary),
            binary
        );
    }

    /// A text without NUL and not blank is indexed with no rejection; the hash and the size
    /// describe the bytes, BOM included; the passages are the split of the text, with or
    /// without the BOM.
    #[test]
    fn text_is_indexed_with_or_without_a_bom(text in prop_oneof![
        "[a-z é\n\r\t😀\u{a0}]{0,300}",
        texts().prop_map(|t| t.replace('\0', "")),
    ]) {
        prop_assume!(!text.chars().all(char::is_whitespace));
        let with_bom_bytes = [b"\xEF\xBB\xBF", text.as_bytes()].concat();
        let plain = snapshot(text.as_bytes());
        let with_bom = snapshot(&with_bom_bytes);
        for (shot, bytes) in [(&plain, text.as_bytes()), (&with_bom, &with_bom_bytes[..])] {
            prop_assert_eq!(shot.status, sermofur_core::records::SourceStatus::Indexed);
            prop_assert_eq!(shot.rejection, None);
            prop_assert_eq!(&shot.hash, &sha256(bytes));
            prop_assert_eq!(shot.size, bytes.len() as i64);
            prop_assert!(!shot.passages.is_empty());
        }
        prop_assert_eq!(&plain.passages, &split(&text));
        prop_assert_eq!(&with_bom.passages, &plain.passages);
    }

    /// Passages are bounded, numbered from 0, never blank, and keep every character that is
    /// not white space, in order.
    #[test]
    fn passages_are_bounded_and_keep_every_character(text in texts()) {
        let passages = split(&text);
        for (index, (number, passage)) in passages.iter().enumerate() {
            prop_assert_eq!(*number as usize, index);
            let length = passage.encode_utf16().count();
            prop_assert!((1..=MAX_PASSAGE_LENGTH).contains(&length));
            prop_assert!(!passage.chars().all(char::is_whitespace));
        }
        let kept: String = passages.iter().map(|(_, p)| non_white(p)).collect();
        prop_assert_eq!(kept, non_white(&text));
    }
}
